// date 2023/12/09 func longestPalindrome(s string) string { res := &#34;&#34; n := len(s) var checkPalindrome func(left, right int) checkPalindrome = func(left, right int) { for left &gt;= 0 &amp;&amp; right &lt; n &amp;&amp; s[left] == s[right] { left-- right++ } if len(s[left+1:right]) &gt; len(res) { res = s[left+1 : right] } } for i := 0; i &lt; n; i++ { checkPalindrome(i, i) checkPalindrome(i, i+1) } return res }

