// date 2020/03/28 func addStrings(num1 string, num2 string) string { ans := &#34;&#34; carry, v1, v2 := 0, 0, 0 i, j := len(num1)-1, len(num2)-1 for i &gt;= 0 || j &gt;= 0 || carry != 0 { v1, v2 = 0, 0 if i &gt;= 0 { v1 = int(num1[i] - &#39;0&#39;) } if j &gt;= 0 { v2 = int(num2[j] - &#39;0&#39;) } t := carry + v1 + v2 carry = t / 10 ans = fmt.Sprintf(&#34;%d&#34;, t % 10) + ans i-- j-- } return ans }

