func strStr(haystack, needle string) int { if len(needle) &lt;= 0 {return 0} n1, n2 := len(haystack), len(needle) for i := 0; i &lt; n1; i++ { if haystack[i] != needle[0] { continue } if i + n2 &gt; n1 { return -1 } if string(haystack[i:i+n]) == needle {return i} } return -1 }151 翻转字符串里的单词# 题目要求：
