// date 2020/03/29 /* 1. 从字符串尾部开始遍历，依次翻转每个单词 2. 遍历字符串的时候主要去掉多余空格，最后的结果也需要去掉多余的空格 */ func reverseWords(s string) string { res, word_res := make([]byte, 0), make([]byte, 0) end := len(s)-1 // 去掉尾部多余的空格 for end &gt;= 0 &amp;&amp; s[end] == &#39; &#39; { end-- } for i := end; i &gt;= 0; i-- { if s[i] != &#39; &#39; { word_res = append(word_res, s[i]) } else { // 找到一个单词 res = append(res, reverseWord(word_res)...) res = append(res, &#39; &#39;) // 去掉中间多余的空格 for i &gt;= 0 &amp;&amp; s[i] == &#39; &#39; { i-- } i++ word_res = word_res[:0] } } if len(word_res) &gt; 0 { res = append(res, reverseWord(word_res)...) } if len(res) &gt; 0 &amp;&amp; res[len(res)-1] == &#39; &#39; { res = res[:len(res)-1] } return string(res) } func reverseWord(word []byte) []byte { i, j := 0, len(word)-1 var c byte for i &lt; j { c = word[i] word[i] = word[j] word[j] = c i++ j-- } return word }246 中心对称数# 题目要求：https://leetcode-cn.com/problems/strobogrammatic-number/
