// date 2020/03/08 // 算法一：两层循环，超时 // 算法二：利用map,时间复杂度O(N),空间复杂度O(N) func findLHS(nums []int) int { m := make(map[int]int, 0) for _, v := range nums { if _, ok := m[v]; ok { m[v]++ } else { m[v] = 1 } } res := 0 for k, v1 := range m { if v2, ok := m[k+1]; ok &amp;&amp; v1+v2 &gt; res { res = v1+v2 } } return res } // 算法三，算法二的优化版 func findLHS(nums []int) int{ res, m := 0, make(map[int]int, 0) for _, v := range nums { if _, ok := m[v]; ok { m[v]++ } else { m[v] = 1 } // cal if v1, ok := m[v-1]; ok &amp;&amp; m[v]+v1 &gt; res { res = v1+m[v] } if v1, ok := m[v+1]; ok &amp;&amp; m[v]+v1 &gt; res { res = v1+m[v] } } return res }674 最长连续递增序列# 题目要求：https://leetcode-cn.com/problems/longest-continuous-increasing-subsequence/
算法分析：
// date 2020/03/08 func findLengthOfLCIS(nums []int) int { if len(nums) == 0 { return 0 } res, temp := 1, 1 for i := 0; i &lt; len(nums)-1; i++ { if nums[i+1] &gt; nums[i] { temp++ } else { temp = 1 } if temp &gt; res { res = temp } } return res }字符串中第一个唯一的字符# func firstUniqChar(s string) int { m := make(map[uint8]int, len(s)) for i := 0; i &lt; len(s); i++ { if _, ok := m[s[i]]; ok { m[s[i]] = -1 } else { m[s[i]] = i } } for i := 0; i &lt; len(s); i++ { if v, ok := m[s[i]]; ok &amp;&amp; v != -1 { return v } } return -1 }翻转字符串里的单词# 题目要求：给定一个字符串，返回其按单词翻转，并去除多余空格的结果。
算法：从字符串的尾部遍历，找到单个单词，并翻转放入其结果，注意空格。
// date 2020/02/02 func reverseWords(s string) string { res, temp := make([]byte, 0), make([]byte, 0) // 存放结果和单个单词 end := len(s)-1 for end &gt;= 0 &amp;&amp; s[end] == &#39; &#39; { end-- } for i := end; i &gt;= 0; i-- { if s[i] != &#39; &#39; { temp = append(temp, s[i]) } else { // find the word res = append(res, reverseWord(temp)...) res = append(res, &#39; &#39;) for i &gt;= 0 &amp;&amp; s[i] == &#39; &#39; { i-- } i++ temp = make([]byte, 0) } } if 0 != len(temp) { res = append(res, reverseWord(temp)...) } if len(res) &gt; 0 &amp;&amp; res[len(res)-1] == &#39; &#39; { res = res[:len(res)-1] } return string(res[:len(res)]) } func reverseWord(word []byte) []byte { s, e := 0, len(word)-1 var t byte for s &lt; e { t = word[s] word[s] = word[e] word[e] = t s++ e-- } return word }820 单词的压缩编码# 题目要求：https://leetcode-cn.com/problems/short-encoding-of-words/
思路分析：考察知识点，字典树
如果一个单词是另一个单词的后缀，则该单词不需要重新编码。
// date 2020/03/28 func minimumLengthEncoding(words []string) int { // 将单词存入哈希表，方便删除 set := make(map[string]string, len(words)) for _, w := range words { set[w] = w } // 查找可能存在的单词后缀，并删除它，注意单词的索引从1开始 for _, word := range words { for i := 1; i &lt; len(word); i++ { key := string(word[i:]) if _, ok := set[key]; ok { delete(set, key) } } } // 统计并返回结果 var res int for word := range set { res += len(word)+1 } return res }

100 相同的树-简单# 题目：
给你两棵二叉树的根节点 p 和 q ，编写一个函数来检验这两棵树是否相同。如果两个树在结构上相同，并且节点具有相同的值，则认为它们是相同的。
分析：
直接递归判断就可以。
从递归可以看到，这是一种自底向上的方式，需要结合左右子树的情况以及当前节点本身，确定最终结果。
// date 2022/10/10 func isSameTree(p *TreeNode, q *TreeNode) bool { if p == nil &amp;&amp; q == nil { return true } if p == nil || q == nil { return false } if p.Val != q.Val { return false } return isSameTree(p.Left, q.Left) &amp;&amp; isSameTree(p.Right, q.Right) }

103 二叉树的锯齿形层序遍历-中等# 题目：
给你二叉树的根节点 root ，返回其节点值的 锯齿形层序遍历 。（即先从左往右，再从右往左进行下一层遍历，以此类推，层与层之间交替进行）。
分析：
正常层序遍历，每层存储结果的时候，先正向再反向。
// date 2023/10/23 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func zigzagLevelOrder(root *TreeNode) [][]int { res := make([][]int, 0, 16) if root == nil { return res } queue := make([]*TreeNode, 0, 16) queue = append(queue, root) isLeftFirst := true for len(queue) != 0 { n := len(queue) lRes := make([]int, n) for i := 0; i &lt; n; i++ { cur := queue[i] if isLeftFirst { lRes[i] = cur.Val } else { lRes[n-1-i] = cur.Val } if cur.Left != nil { queue = append(queue, cur.Left) } if cur.Right != nil { queue = append(queue, cur.Right) } } queue = queue[n:] res = append(res, lRes) isLeftFirst = !isLeftFirst } return res }

105 从前序与中序遍历序列构造二叉树-中等# 题目：
给定两个整数数组 preorder 和 inorder ，其中 preorder 是二叉树的先序遍历， inorder 是同一棵树的中序遍历，请构造二叉树并返回其根节点。
分析：
前序序列是按照「根左右」的顺序遍历，而中序序列是按照「左根右」的顺序遍历，所以根节点肯定是前序序列中的第一个元素，然后再中序序列中找到该根节点的位置，将其分为左右子树，递归构建。
// date 2023/10/23 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func buildTree(preorder []int, inorder []int) *TreeNode { if len(preorder) == 0 { return nil } root := &amp;TreeNode{Val: preorder[0]} index := 0 for i := 0; i &lt; len(inorder); i++ { if inorder[i] == preorder[0] { index = i break } } root.Left = buildTree(preorder[1:index+1], inorder[0:index]) root.Right = buildTree(preorder[index+1:], inorder[index+1:]) return root }

106从中序与后序遍历序列构造二叉树-中等# 题目：
给定两个整数数组 inorder 和 postorder ，其中 inorder 是二叉树的中序遍历， postorder 是同一棵树的后序遍历，请你构造并返回这颗 二叉树 。
分析：
后序序列中的最后一个元素为根节点，然后再中序序列中找到根节点的位置，依次递归构造左右子树。
// date 2023/10/23 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func buildTree(inorder []int, postorder []int) *TreeNode { if len(inorder) == 0 { return nil } n := len(postorder) index := 0 root := &amp;TreeNode{Val: postorder[n-1]} for i := 0; i &lt; n; i++ { if inorder[i] == postorder[n-1] { index = i break } } // inorder 左右根 // postorder 左右根 root.Left = buildTree(inorder[0:index], postorder[0:index]) // 一样长 root.Right = buildTree(inorder[index+1:], postorder[index:n-1]) // 一样的起点 return root }

107 二叉树的层序遍历2-中等# 题目：
给你二叉树的根节点 root ，返回其节点值 自底向上的层序遍历 。 （即按从叶子节点所在层到根节点所在的层，逐层从左向右遍历）
分析：
这里先正常层序遍历，然后再将结果集反转一下。【推荐该算法】
想了下，暂时没有比这更好的算法，因为向数组的头部插入数据，涉及拷贝，所以并不能够将每一层的结果一次性放入指定位置。
// date 2023/10/23 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func levelOrderBottom(root *TreeNode) [][]int { res := make([][]int, 0, 16) if root == nil { return res } queue := make([]*TreeNode, 0, 16) queue = append(queue, root) for len(queue) != 0 { n := len(queue) lRes := make([]int, 0, 16) for i := 0; i &lt; n; i++ { cur := queue[i] lRes = append(lRes, cur.Val) if cur.Left != nil { queue = append(queue, cur.Left) } if cur.Right != nil { queue = append(queue, cur.Right) } } res = append(res, lRes) queue = queue[n:] } i, j := 0, len(res)-1 for i &lt; j { res[i], res[j] = res[j], res[i] i++ j-- } return res }

108 将有序数组转换为二叉搜索树-简单# 题目：
给你一个整数数组 nums，其中元素已经按升序排列，请你将其转换为一个 高度平衡 的二叉搜索树。
高度平衡二叉树是一棵满足「每个节点的左右两个子树的高度差的绝对值不超过 1」的二叉树。
分析：
跟【从中序和后序序列构造二叉树】类似，为了保持高度平衡，从有序数组中去中间值作为根，依次递归生成左右子树。
// date 2023/10/23 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func sortedArrayToBST(nums []int) *TreeNode { if len(nums) == 0 { return nil } mid := len(nums)/2 root := &amp;TreeNode{Val: nums[mid]} root.Left = sortedArrayToBST(nums[0:mid]) root.Right = sortedArrayToBST(nums[mid+1:]) return root }

109 有序链表转换为二叉搜索树-中等# 题目：
给定一个单链表的头节点 head，其中的元素按升序排列，将其转换为高度平衡的二叉搜索树。
一个高度平衡二叉树是指一个二叉树每个节点的左右两个子树的高度差不超过 1。
分析：
这个题目跟 108 题目类似，只不过从【有序数组】换成了【有序链表】。但思路是一样的，找到中间节点，递归构造。
// date 2023/10/23 /** * Definition for singly-linked list. * type ListNode struct { * Val int * Next *ListNode * } */ /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func sortedListToBST(head *ListNode) *TreeNode { if head == nil { return nil } if head.Next == nil { return &amp;TreeNode{Val: head.Val} } var pre, slow, fast *ListNode slow = head fast = head for fast != nil &amp;&amp; fast.Next != nil { pre = slow slow = slow.Next fast = fast.Next.Next } pre.Next = nil root := &amp;TreeNode{Val: slow.Val} root.Left = sortedListToBST(head) slow = slow.Next if slow == nil { return root } root.Right = sortedListToBST(slow) return root }

111 二叉树的最小深度-简单# 给定一个二叉树，找出其最小深度。
最小深度是从根节点到最近叶子节点的最短路径上的节点数量。
**说明：**叶子节点是指没有子节点的节点。
算法1：递归
这里还是递归的思想，只不过返回左右子树其中的最小值。需要注意的是，如果不存在左子树，则返回右子树的最小深度并加1，同理右子树也是如此。
// date 2020/03/21 func minDepth(root *TreeNode) int { if root == nil { return 0 } if root.Left == nil { return 1+minDepth(root.Right) } if root.Right == nil { return 1+minDepth(root.Left) } l, r := minDepth(root.Left), minDepth(root.Right) if l &gt; r { return r+1 } return l+1 }算法2：bfs【推荐该算法】
该算法与层序遍历类似，依次入队，判断当前节点是否同时没有左右子树，从而找到最近的一层，即为最小深度。
// date 2022/10/19 func minDepth(root *TreeNode) int { if root == nil { return 0 } queue := make([]*TreeNode, 0, 16) queue = append(queue, root) n := len(queue) var depth int for len(queue) != 0 { depth++ n = len(queue) for i := 0; i &lt; n; i++ { cur := queue[i] // 已经找到了最近的一层 if cur.Left == nil &amp;&amp; cur.Right == nil { return depth } if cur.Left != nil { queue = append(queue, cur.Left) } if cur.Right != nil { queue = append(queue, cur.Right) } } queue = queue[n:] } return depth }算法3：dfs深度优先搜索
这里跟递归类似，只是写法不一样。
func minDepth(root *TreeNode) int { var dfs func(root *TreeNode, depth int) int dfs = func(root *TreeNode, depth int) int { if root == nil { return depth } depth++ if root.Left == nil &amp;&amp; root.Right == nil { return depth } if root.Left == nil { return dfs(root.Right, depth) } if root.Right == nil { return dfs(root.Left, depth) } l, r := dfs(root.Left, depth), dfs(root.Right, depth) if l &lt; r { return l } return r } return dfs(root, 0) }

112 路径总和-简单# 题目：
给你二叉树的根节点 root 和一个表示目标和的整数 targetSum 。判断该树中是否存在 根节点到叶子节点 的路径，这条路径上所有节点值相加等于目标和 targetSum 。如果存在，返回 true ；否则，返回 false 。
叶子节点 是指没有子节点的节点。
分析：
算法1：递归
这种递归是自顶向下的方式，通过结合当前节点值，向下一层级传递新的目标值，以判断到达叶子节点时是否满足条件。
// date 2022/10/19 func hasPathSum(root *TreeNode, targetSum int) bool { if root == nil { return false } targetSum -= root.Val if root.Left == nil &amp;&amp; root.Right == nil { return targetSum == 0 } return hasPathSum(root.Left, targetSum) || hasPathSum(root.Right, targetSum) }算法2：【推荐该算法】
迭代，类似层序遍历，当遍历到叶子节点时，判断值是否为零
// date 2023/10/18 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func hasPathSum(root *TreeNode, targetSum int) bool { if root == nil { return false } queue := make([]*TreeNode, 0, 16) csum := make([]int, 0, 16) queue = append(queue, root) csum = append(csum, targetSum-root.Val) n := len(queue) for len(queue) != 0 { n = len(queue) for i := 0; i &lt; n; i++ { cur := queue[i] // 找到叶子节点 if cur.Left == nil &amp;&amp; cur.Right == nil &amp;&amp; csum[i] == 0 { return true } if cur.Left != nil { queue = append(queue, cur.Left) csum = append(csum, csum[i] - cur.Left.Val) } if cur.Right != nil { queue = append(queue, cur.Right) csum = append(csum, csum[i] - cur.Right.Val) } } queue = queue[n:] csum = csum[n:] } return false }

114 二叉树展开为链表-中等# 题目：
给你二叉树的根结点 root ，请你将它展开为一个单链表：
展开后的单链表应该同样使用 TreeNode ，其中 right 子指针指向链表中下一个结点，而左子指针始终为 null 。 展开后的单链表应该与二叉树 先序遍历 顺序相同。 分析：
// date 2023/10/23 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func flatten(root *TreeNode) { cur := root for cur != nil { if cur.Left != nil { next := cur.Left pre := next for pre.Right != nil { pre = pre.Right } pre.Right = cur.Right cur.Left = nil cur.Right = next } cur = cur.Right } }

1161 最大层内元素和-中等# 题目：
给你一个二叉树的根节点 root。设根节点位于二叉树的第 1 层，而根节点的子节点位于第 2 层，依此类推。
请返回层内元素之和 最大 的那几层（可能只有一层）的层号，并返回其中 最小 的那个。
分析：
这里就是层序遍历，根据每层的结果更新最终的结果即可。
// date 2023/10/28 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func maxLevelSum(root *TreeNode) int { if root == nil { return 0 } queue := make([]*TreeNode, 0, 16) queue = append(queue, root) n := len(queue) ls := 0 // level sum lsMax := math.Inf(-1) level, res := 1, 1 for len(queue) != 0 { n = len(queue) ls = 0 for i := 0; i &lt; n; i++ { cur := queue[i] ls += cur.Val if cur.Left != nil { queue = append(queue, cur.Left) } if cur.Right != nil { queue = append(queue, cur.Right) } } if float64(ls) &gt; lsMax { lsMax = float64(ls) res = level } queue = queue[n:] level++ } return res }

116 填充每个节点的下一个右侧节点-中等# 题目：
给定一个 完美二叉树 ，其所有叶子节点都在同一层，每个父节点都有两个子节点。二叉树定义如下：
struct Node { int val; Node *left; Node *right; Node *next; }填充它的每个 next 指针，让这个指针指向其下一个右侧节点。如果找不到下一个右侧节点，则将 next 指针设置为 NULL。
初始状态下，所有 next 指针都被设置为 NULL。
分析：
// date 2023/10/23 /** * Definition for a Node. * type Node struct { * Val int * Left *Node * Right *Node * Next *Node * } */ func connect(root *Node) *Node { if root == nil { return nil } queue := make([]*Node, 0, 16) queue = append(queue, root) for len(queue) != 0 { n := len(queue) for i := 0; i &lt; n; i++ { cur := queue[i] if i + 1 &lt; n { cur.Next = queue[i+1] } if cur.Left != nil { queue = append(queue, cur.Left) } if cur.Right != nil { queue = append(queue, cur.Right) } } queue = queue[n:] } return root }

117 填充每个节点的下一个右侧节点指针2-中等# 题目：
给定一个二叉树：
struct Node { int val; Node *left; Node *right; Node *next; }填充它的每个 next 指针，让这个指针指向其下一个右侧节点。如果找不到下一个右侧节点，则将 next 指针设置为 NULL 。
初始状态下，所有 next 指针都被设置为 NULL 。
分析：
// date 2023/10/23 /** * Definition for a Node. * type Node struct { * Val int * Left *Node * Right *Node * Next *Node * } */ func connect(root *Node) *Node { if root == nil { return root } queue := make([]*Node, 0, 16) queue = append(queue, root) for len(queue) != 0 { n := len(queue) for i := 0; i &lt; n; i++ { cur := queue[i] if i+1 &lt; n { cur.Next = queue[i+1] } if cur.Left != nil { queue = append(queue, cur.Left) } if cur.Right != nil { queue = append(queue, cur.Right) } } queue = queue[n:] } return root }算法2：【推荐该算法，很巧妙】
像链表一样的处理。
// date 2023/10/23 /** * Definition for a Node. * type Node struct { * Val int * Left *Node * Right *Node * Next *Node * } */ func connect(root *Node) *Node { if root == nil { return root } cur := root for cur != nil { dumy := &amp;Node{} pre := dumy for cur != nil { if cur.Left != nil { pre.Next = cur.Left pre = pre.Next } if cur.Right != nil { pre.Next = cur.Right pre = pre.Next } cur = cur.Next } cur = dumy.Next } return root }

129 求从根节点到叶子节点数字之和-中等# 给你一个二叉树的根节点 root ，树中每个节点都存放有一个 0 到 9 之间的数字。 每条从根节点到叶节点的路径都代表一个数字：
例如，从根节点到叶节点的路径 1 -&gt; 2 -&gt; 3 表示数字 123 。 计算从根节点到叶节点生成的 所有数字之和 。
叶节点 是指没有子节点的节点。
分析：
自顶向下递归，并且携带已知的值；当遇到叶子节点时计算到结果中。
// date 2023/10/23 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func sumNumbers(root *TreeNode) int { var ans int var dfs func(root *TreeNode, has int) dfs = func(root *TreeNode, has int) { if root == nil { return } if root.Left == nil &amp;&amp; root.Right == nil { ans += has + root.Val return } has = (has + root.Val) * 10 if root.Left != nil { dfs(root.Left, has) } if root.Right != nil { dfs(root.Right, has) } } dfs(root, 0) return ans }

1302 层数最深叶子节点的和-中等# 题目：
给你一棵二叉树的根节点 root ，请你返回 层数最深的叶子节点的和 。
分析：
就是层序遍历，只存储当前层结果，那么最后一次结果就是答案。
// date 2023/20/28 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func deepestLeavesSum(root *TreeNode) int { var res int if root == nil { return res } queue := make([]*TreeNode, 0, 16) queue = append(queue, root) for len(queue) != 0 { n := len(queue) res = 0 for i := 0; i &lt; n; i++ { cur := queue[i] res += cur.Val if cur.Left != nil { queue = append(queue, cur.Left) } if cur.Right != nil { queue = append(queue, cur.Right) } } queue = queue[n:] } return res }

1305 两棵二叉搜索树的所有元素-中等# 题目：
给你 root1 和 root2 这两棵二叉搜索树。请你返回一个列表，其中包含 两棵树 中的所有整数并按 升序 排序。.
分析：
前序遍历，变成两个有序数组，然后归并。
// date 2023/10/30 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func getAllElements(root1 *TreeNode, root2 *TreeNode) []int { s1 := bst2array(root1) s2 := bst2array(root2) ans := make([]int, 0, 16) i, j := 0, 0 k1, k2 := len(s1), len(s2) for i &lt; k1 || j &lt; k2 { if i &gt;= k1 { break } if j &gt;= k2 { break } if s1[i] &lt; s2[j] { ans = append(ans, s1[i]) i++ } else { ans = append(ans, s2[j]) j++ } } if i &lt; k1 { ans = append(ans, s1[i:]...) } if j &lt; k2 { ans = append(ans, s2[j:]...) } return ans } func bst2array(r1 *TreeNode) []int { ans := make([]int, 0, 16) var dfs func(root *TreeNode) dfs = func(root *TreeNode) { if root == nil { return } dfs(root.Left) ans = append(ans, root.Val) dfs(root.Right) } dfs(r1) return ans }

1609 奇偶树-中等# 题目：
如果一棵二叉树满足下述几个条件，则可以称为 奇偶树 ：
二叉树根节点所在层下标为 0 ，根的子节点所在层下标为 1 ，根的孙节点所在层下标为 2 ，依此类推。 偶数下标 层上的所有节点的值都是 奇 整数，从左到右按顺序 严格递增 奇数下标 层上的所有节点的值都是 偶 整数，从左到右按顺序 严格递减 给你二叉树的根节点，如果二叉树为 奇偶树 ，则返回 true ，否则返回 false 。
分析：
没啥好说的，就是基本的层序遍历。
// date 2023/10/30 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func isEvenOddTree(root *TreeNode) bool { if root == nil { return false } queue := make([]*TreeNode, 0, 16) queue = append(queue, root) var preVal int isEvenIdx := false for len(queue) != 0 { n := len(queue) for i := 0; i &lt; n; i++ { cur := queue[i] if isEvenIdx { if cur.Val % 2 == 1 { return false } } else { if cur.Val % 2 == 0 { return false } } if i == 0 { preVal = cur.Val } else { if isEvenIdx { // 严格递减 if cur.Val &gt;= preVal { return false } } else { if cur.Val &lt;= preVal { return false } } preVal = cur.Val } if cur.Left != nil { queue = append(queue, cur.Left) } if cur.Right != nil { queue = append(queue, cur.Right) } } queue = queue[n:] isEvenIdx = !isEvenIdx } return true }

