// date 2023/10/23 func rightSideView(root *TreeNode) []int { res := make([]int, 0) if root == nil { return res } stack := make([]*TreeNode, 0) stack = append(stack, root) for len(stack) != 0 { n := len(stack) res = append(res, stack[0].Val) for i := 0; i &lt; n; i++ { if stack[i].Right != nil { stack = append(stack, stack[i].Right) } if stack[i].Left != nil { stack = append(stack, stack[i].Left) } } stack = stack[n:] } return res }

