层序遍历，找每一层最大值
// date 2026/06/06 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func largestValues(root *TreeNode) []int { res := make([]int, 0, 8) if root == nil { return res } queue := make([]*TreeNode, 0, 4) queue = append(queue, root) for len(queue) != 0 { n := len(queue) maxVal := queue[0].Val for i := 0; i &lt; n; i++ { cur := queue[i] if cur.Val &gt; maxVal { maxVal = cur.Val } if cur.Left != nil { queue = append(queue, cur.Left) } if cur.Right != nil { queue = append(queue, cur.Right) } } res = append(res, maxVal) queue = queue[n:] } return res }

530 二叉搜索树的最小绝对差-中等# 题目：
给你一个二叉搜索树的根节点 root ，返回 树中任意两不同节点值之间的最小差值 。
差值是一个正数，其数值等于两值之差的绝对值。
分析：
递归中序遍历，求相邻元素的最小值。
// date 2023/10/30 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func getMinimumDifference(root *TreeNode) int { res := 1 &lt;&lt; 32 - 1 preVal := -1 var dfs func(root *TreeNode) dfs = func(root *TreeNode) { if root == nil { return } dfs(root.Left) if preVal != -1 &amp;&amp; root.Val - preVal &lt; res { res = root.Val - preVal } preVal = root.Val dfs(root.Right) } dfs(root) return res }

545 二叉树的边界-中等# 题目：
给定一个二叉树，按逆时针返回其边界。
分析：
分别求其左边界，右边界，和所有的叶子节点，用visited辅助去重，算法如下：
// date 2020/02/23 func boundaryOfBinaryTree(root *TreeNode) []int { if root == nil { return []int{} } res := make([]int, 0) left, right := make([]*TreeNode, 0), make([]*TreeNode, 0) visited := make(map[*TreeNode]int, 0) res = append(res, root.Val) visited[root] = 1 // find left node pre := root.Left for pre != nil { left = append(left, pre) visited[pre] = 1 if pre.Left != nil { pre = pre.Left } else { pre = pre.Right } } // find right node pre = root.Right for pre != nil { right = append(right, pre) visited[pre] = 1 if pre.Right != nil { pre = pre.Right } else { pre = pre.Left } } leafs := findLeafs(root) // make res for i := 0; i &lt; len(left); i++ { res = append(res, left[i].Val) } for i := 0; i &lt; len(leafs); i++ { if _, ok := visited[leafs[i]]; ok { continue } res = append(res, ,leafs[i].Val) } for i := len(right) - 1; i &gt;= 0; i-- { res = append(res, right[i].Val) } return res } func findLeafs(root *TreeNode) []*TreeNode { res := make([]*TreeNode, 0) if root == nil { return res } if root.Left == nil &amp;&amp; root.Right == nil { res = append(res, root) return res } res = append(res, findLeafs(root.Left)...) res = append(res, findLeafs(root.Right)...) return res }

559 N叉树的最大深度-简单# 题目：
给定一个 N 叉树，找到其最大深度。
最大深度是指从根节点到最远叶子节点的最长路径上的节点总数。
N 叉树输入按层序遍历序列化表示，每组子节点由空值分隔（请参见示例）。
解题思路
// date 2024/02/20 // 解法1，递归 /** * Definition for a Node. * type Node struct { * Val int * Children []*Node * } */ func maxDepth(root *Node) int { ans := 0 var dfs func(root *Node) int dfs = func(root *Node) int { if root == nil { return 0 } if len(root.Children) == 0 { if ans &lt; 1 { ans = 1 } return 1 } temp := 0 for i := 0; i &lt; len(root.Children); i++ { res := dfs(root.Children[i]) if res &gt; temp { temp = res } } temp++ if temp &gt; ans { ans = temp } return temp } dfs(root) return ans } // 解法2，bfs，层序遍历 func maxDepth(root *Node) int { if root == nil { return 0 } if len(root.Children) == 0 { return 1 } ans := 0 queue := make([]*Node, 0, 16) queue = append(queue, root) for len(queue) != 0 { n := len(queue) for i := 0; i &lt; n; i++ { cur := queue[i] for j := 0; j &lt; len(cur.Children); j++ { if cur.Children[j] != nil { queue = append(queue, cur.Children[j]) } } } queue = queue[n:] ans++ } return ans }

589 N叉树的前序遍历-简单# 题目：
给定一个 n 叉树的根节点 root ，返回 其节点值的 前序遍历 。
n 叉树 在输入中按层序遍历进行序列化表示，每组子节点由空值 null 分隔（请参见示例）。
解题思路
算法1：递归
// date 2022/10/21 func preorder(root *Node) []int { res := make([]int, 0, 16) if root == nil { return res } res = append(res, root.Val) for i := 0; i &lt; len(root.Children); i++ { res = append(res, preorder(root.Children[i])...) } return res }算法2：迭代
// date 2022/10/19 func preorder(root *Node) []int { res := make([]int, 0, 16) if root == nil { return res } stack := make([]*Node, 0, 16) stack = append(stack, root) for len(stack) != 0 { cur := stack[len(stack)-1] stack = stack[:len(stack)-1] res = append(res, cur.Val) for i := len(cur.Children)-1; i &gt;= 0; i-- { // 直接逆序存放，出栈时就是最左边的那个 if cur.Children[i] != nil { stack = append(stack, cur.Children[i]) } } } return res }

590 N叉树的后序遍历-简单# 给定一个 n 叉树的根节点 root ，返回 其节点值的 后序遍历 。
n 叉树 在输入中按层序遍历进行序列化表示，每组子节点由空值 null 分隔（请参见示例）。
分析：
算法1：递归
// date 2022/10/12 func postorder(root *Node) []int { if root == nil { return []int{} } res := make([]int, 0, 16) for i := 0; i &lt; len(root.Children); i++ { res = append(res, postorder(root.Children[i])...) } res = append(res, root.Val) return res }算法2：迭代【推荐该算法】
// date 2023/10/31 /** * Definition for a Node. * type Node struct { * Val int * Children []*Node * } */ func postorder(root *Node) []int { if root == nil { return []int{} } res := make([]int, 0, 16) stack := make([]*Node, 0, 16) stack = append(stack, root) visited := make(map[*Node]bool, 16) for len(stack) != 0 { cur := stack[len(stack)-1] // 如果当前节点为叶子节点，或者所有子结点已经遍历过，直接追加结果并更新栈 if len(cur.Children) == 0 || visited[cur] { res = append(res, cur.Val) stack = stack[:len(stack)-1] continue } // 入栈当前节点的所有子结点 for i := len(cur.Children)-1; i &gt;= 0; i-- { if cur.Children[i] != nil { stack = append(stack, cur.Children[i]) } } // 标记当前结点的所有子结点已经入栈 visited[cur] = true } return res }

617 合并二叉树-简单# 给你两棵二叉树： root1 和 root2 。
想象一下，当你将其中一棵覆盖到另一棵之上时，两棵树上的一些节点将会重叠（而另一些不会）。你需要将这两棵树合并成一棵新二叉树。合并的规则是：如果两个节点重叠，那么将这两个节点的值相加作为合并后节点的新值；否则，不为 null 的节点将直接作为新二叉树的节点。 返回合并后的二叉树。 注意: 合并过程必须从两个树的根节点开始。
分析：
递归覆盖计算。
// date 2023/10/25 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func mergeTrees(root1 *TreeNode, root2 *TreeNode) *TreeNode { if root1 == nil { return root2 } if root2 == nil { return root1 } root1.Val += root2.Val root1.Left = mergeTrees(root1.Left, root2.Left) root1.Right = mergeTrees(root1.Right, root2.Right) return root1 }

637 二叉树的层平均值-简单# 题目：
给定一个非空二叉树的根节点 root , 以数组的形式返回每一层节点的平均值。与实际答案相差 10-5 以内的答案可以被接受。
分析：
没啥好说的，就是算它。
// date 2023/10/25 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func averageOfLevels(root *TreeNode) []float64 { res := make([]float64, 0, 16) if root == nil { return res } queue := make([]*TreeNode, 0, 16) queue = append(queue, root) for len(queue) != 0 { n := len(queue) levelSum := 0 for i := 0; i &lt; n; i++ { cur := queue[i] levelSum += cur.Val if cur.Left != nil { queue = append(queue, cur.Left) } if cur.Right != nil { queue = append(queue, cur.Right) } } res = append(res, float64(levelSum) / float64(n)) queue = queue[n:] } return res }

653 两数之和4-输入二叉搜索树-简单# 题目：
给定一个二叉搜索树 root 和一个目标结果 k，如果二叉搜索树中存在两个元素且它们的和等于给定的目标结果，则返回 true。
分析：【推荐该算法】
深度搜索，记录已经遍历过的节点。
// date 2023/10/26 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func findTarget(root *TreeNode, k int) bool { var res bool has := make(map[int]struct{}, 16) var dfs func(root *TreeNode) dfs = func(root *TreeNode) { if root == nil { return } if _, ok := has[k-root.Val]; ok { res = true return } has[root.Val] = struct{}{} dfs(root.Left) dfs(root.Right) } dfs(root) return res }算法2：
因为二叉搜索树的前序遍历序列为递增序列，所以可以先将二叉搜索树转换为递增数组，然后从排序数组中求两数之和。
// date 2023/10/26 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func findTarget(root *TreeNode, k int) bool { nums := preOrder(root) i, j := 0, len(nums)-1 for i &lt; j { tg := nums[i] + nums[j] if tg == k { return true } if tg &lt; k { i++ } if tg &gt; k { j-- } } return false } func preOrder(root *TreeNode) []int { nums := make([]int, 0, 16) stack := make([]*TreeNode, 0, 16) for root != nil || len(stack) != 0 { for root != nil { stack = append(stack, root) root = root.Left } root = stack[len(stack)-1] stack = stack[:len(stack)-1] nums = append(nums, root.Val) root = root.Right } return nums }

654 最大二叉树-中等# 题目：
给定一个不重复的整数数组 nums 。 最大二叉树 可以用下面的算法从 nums 递归地构建:
创建一个根节点，其值为 nums 中的最大值。 递归地在最大值 左边 的 子数组前缀上 构建左子树。 递归地在最大值 右边 的 子数组后缀上 构建右子树。 返回 nums 构建的 最大二叉树 。
分析：
找到数组中的最大值，然后递归构造。
// date 2023/10/26 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func constructMaximumBinaryTree(nums []int) *TreeNode { if len(nums) == 0 { return nil } if len(nums) == 1 { return &amp;TreeNode{Val: nums[0]} } // find the max idx := 0 for i, v := range nums { if v &gt; nums[idx] { idx = i } } root := &amp;TreeNode{Val: nums[idx]} root.Left = constructMaximumBinaryTree(nums[:idx]) root.Right = constructMaximumBinaryTree(nums[idx+1:]) return root } // date 2024/10/10 // 补充 dfs 函数版本 func constructMaximumBinaryTree(nums []int) *TreeNode { var dfs func(left, right int) *TreeNode // [left, right) dfs = func(left, right int) *TreeNode { if left &gt;= right { return nil } idx := left for i := left+1; i &lt; right; i++ { if nums[idx] &lt; nums[i] { idx = i } } root := &amp;TreeNode{Val: nums[idx]} root.Left = dfs(left, idx) root.Right = dfs(idx+1, right) return root } return dfs(0, len(nums)) }

669 修剪二叉搜索树-中等# 题目：
给你二叉搜索树的根节点 root ，同时给定最小边界low 和最大边界 high。通过修剪二叉搜索树，使得所有节点的值在[low, high]中。修剪树 不应该 改变保留在树中的元素的相对结构 (即，如果没有被移除，原有的父代子代关系都应当保留)。 可以证明，存在 唯一的答案 。
所以结果应当返回修剪好的二叉搜索树的新的根节点。注意，根节点可能会根据给定的边界发生改变。
分析：
根据二叉搜索树特征，直接修剪。
// date 2023/11/01 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func trimBST(root *TreeNode, low int, high int) *TreeNode { if root == nil { return nil } if root.Val &lt; low { // 说明左子树完全不需要，直接舍弃 // 直接修剪右子树 return trimBST(root.Right, low, high) } if root.Val &gt; high { // 同理，舍弃右子树，直接修剪左子树 return trimBST(root.Left, low, high) } root.Left = trimBST(root.Left, low, high) root.Right = trimBST(root.Right, low, high) return root }

700 二叉搜索树中的搜索-简单# 题目：
给定二叉搜索树（BST）的根节点 root 和一个整数值 val。
你需要在 BST 中找到节点值等于 val 的节点。 返回以该节点为根的子树。 如果节点不存在，则返回 null 。
分析：
根据二叉搜索树的特性，直接递归搜索即可。
// date 2023/10/30 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func searchBST(root *TreeNode, val int) *TreeNode { if root == nil { return nil } if root.Val == val { return root } if root.Val &lt; val { return searchBST(root.Right, val) } return searchBST(root.Left, val) }

701 二叉搜索树的插入操作-中等# 题目：
给定二叉搜索树（BST）的根节点 root 和要插入树中的值 value ，将值插入二叉搜索树。 返回插入后二叉搜索树的根节点。 输入数据 保证 ，新值和原始二叉搜索树中的任意节点值都不同。
注意，可能存在多种有效的插入方式，只要树在插入后仍保持为二叉搜索树即可。 你可以返回 任意有效的结果 。
分析：
// date 2023/10/30 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func insertIntoBST(root *TreeNode, val int) *TreeNode { if root == nil { return &amp;TreeNode{Val: val} } if root.Val &gt; val { if root.Left == nil { root.Left = &amp;TreeNode{Val: val} } else { insertIntoBST(root.Left, val) } } if root.Val &lt; val { if root.Right == nil { root.Right = &amp;TreeNode{Val: val} } else { insertIntoBST(root.Right, val) } } return root }

783 二叉搜索树节点最小距离-简单# 题目：
给你一个二叉搜索树的根节点 root ，返回 树中任意两不同节点值之间的最小差值 。
差值是一个正数，其数值等于两值之差的绝对值。
分析：
中序遍历，相邻的两个差值最小。
// date 2023/10/27 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func minDiffInBST(root *TreeNode) int { var ans, pre int ans = math.MaxInt64 - 1 pre = -1 var dfs func(root *TreeNode) dfs = func(root *TreeNode) { if root == nil { return } dfs(root.Left) if pre != -1 &amp;&amp; root.Val - pre &lt; ans { ans = root.Val - pre } pre = root.Val dfs(root.Right) } dfs(root) return ans }迭代版
// date 2023/10/27 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func minDiffInBST(root *TreeNode) int { var ans, pre int ans = math.MaxInt64 - 1 pre = -1 stack := make([]*TreeNode, 0, 16) for root != nil || len(stack) != 0 { for root != nil { stack = append(stack, root) root = root.Left } if len(stack) != 0 { root = stack[len(stack)-1] stack = stack[:len(stack)-1] if pre != -1 &amp;&amp; root.Val - pre &lt; ans { ans = root.Val - pre } // update pre pre = root.Val root = root.Right } } return ans }

814 二叉树剪枝-中等# 题目：
给你二叉树的根结点 root ，此外树的每个结点的值要么是 0 ，要么是 1 。 返回移除了所有不包含 1 的子树的原二叉树。 节点 node 的子树为 node 本身加上所有 node 的后代。
分析：
算法1【推荐该算法】
先递归左右子树，然后判断子树是否为空，以及当前节点是否为零，如果是直接剪枝。
// date 2023/10/27 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func pruneTree(root *TreeNode) *TreeNode { if root == nil { return root } root.Left = pruneTree(root.Left) root.Right = pruneTree(root.Right) if root.Left == nil &amp;&amp; root.Right == nil &amp;&amp; root.Val == 0 { return nil } return root }算法2
使用 containsOne() 递归判断节点以及节点的左右子树是否包含1，如果不包含，直接剪枝。
// date 2023/10/27 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func pruneTree(root *TreeNode) *TreeNode { if containsOne(root) { return root } return nil } func containsOne(root *TreeNode) bool { if root == nil { return false } l, r := containsOne(root.Left), containsOne(root.Right) if !l { root.Left = nil } if !r { root.Right = nil } return root.Val == 1 || l || r }

938 二叉搜索树的范围和-简单# 题目：
给定二叉搜索树的根结点 root，返回值位于范围 [low, high] 之间的所有结点的值的和。
分析：
算法1：深度优先搜索
// date 2023/10/28 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func rangeSumBST(root *TreeNode, low int, high int) int { var sum int var dfs func(root *TreeNode) dfs = func(root *TreeNode) { if root == nil { return } if low &lt;= root.Val &amp;&amp; root.Val &lt;= high { sum += root.Val } dfs(root.Left) dfs(root.Right) } dfs(root) return sum }算法2：
递归
// date 2023/10/28 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func rangeSumBST(root *TreeNode, low int, high int) int { if root == nil { return 0 } var sum int sum += rangeSumBST(root.Left, low, high) sum += rangeSumBST(root.Right, low, high) if root.Val &lt;= high &amp;&amp; root.Val &gt;= low { sum += root.Val } return sum }

965 单值二叉树-中等# 题目：
如果二叉树每个节点都具有相同的值，那么该二叉树就是单值二叉树。
只有给定的树是单值二叉树时，才返回 true，否则返回 false。
分析：
递归比较即可。
// date 2023/10/28 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func isUnivalTree(root *TreeNode) bool { if root == nil { return false } var isSame func(root *TreeNode, target int) bool isSame = func(root *TreeNode, target int) bool { if root == nil { return true } return root.Val == target &amp;&amp; isSame(root.Left, target) &amp;&amp; isSame(root.Right, target) } return isSame(root, root.Val) }

993 二叉树的堂兄弟节点-简单# 题目：
在二叉树中，根节点位于深度 0 处，每个深度为 k 的节点的子节点位于深度 k+1 处。 如果二叉树的两个节点深度相同，但 父节点不同 ，则它们是一对堂兄弟节点。 我们给出了具有唯一值的二叉树的根节点 root ，以及树中两个不同节点的值 x 和 y 。 只有与值 x 和 y 对应的节点是堂兄弟节点时，才返回 true 。否则，返回 false。
分析：
算法1：
通过查找 x,y 的父结点以及深度来进行判断。这里的算法需要遍历树两次。
func isCousins(root *TreeNode, x int, y int) bool { xf, xd := findFatherAndDepth(root, x) yf, yd := findFatherAndDepth(root, y) return xd == yd &amp;&amp; xf != yf } func findFatherAndDepth(root *TreeNode, v int) (*TreeNode, int) { if root == nil || root.Val == v { return nil, 0 } if root.Left != nil &amp;&amp; root.Left.Val == v { return root, 1 } if root.Right != nil &amp;&amp; root.Right.Val == v { return root, 1 } l, lv := findFatherAndDepth(root.Left, v) r, rv := findFatherAndDepth(root.Right, v) if l != nil { return l, lv+1 } return r, rv+1 }算法2：【推荐该算法】
这里用深度优先搜索只遍历一次，搜索过程中记录x,y的深度和父结点。
// date 2022/10/02 func isCousins(root *TreeNode, x int, y int) bool { if root == nil {return false} xd, yd := 0, 0 // 存储x,y的深度 f := make(map[int]*TreeNode, 2) // 存储x,y父结点 path := make([]*TreeNode, 0, 16) var dfs func(root *TreeNode) dfs = func(root *TreeNode) { if root == nil { return } path = append(path, root) defer func() { path = path[:len(path)-1] }() if root.Val == x { xd = len(path) if len(path) &gt; 1 { f[x] = path[len(path)-2] } } else if root.Val == y { yd = len(path) if len(path) &gt; 1 { f[y] = path[len(path)-2] } } dfs(root.Left) dfs(root.Right) } dfs(root) xf, ok1 := f[x] yf, ok2 := f[y] return ok1 &amp;&amp; ok2 &amp;&amp; xf != yf &amp;&amp; xd == yd }另一个写法
// date 2023/10/28 /** * Definition for a binary tree node. * type TreeNode struct { * Val int * Left *TreeNode * Right *TreeNode * } */ func isCousins(root *TreeNode, x int, y int) bool { // 深度一样，且父结点不同 xd, yd := 0, 0 var xf, yf *TreeNode var dfs func(root *TreeNode, depth int) dfs = func(root *TreeNode, depth int) { if root == nil { return } if root.Left != nil { if root.Left.Val == x { xd = depth+1 xf = root } if root.Left.Val == y { yd = depth+1 yf = root } } if root.Right != nil { if root.Right.Val == x { xd = depth+1 xf = root } if root.Right.Val == y { yd = depth+1 yf = root } } dfs(root.Left, depth+1) dfs(root.Right, depth+1) } dfs(root, 0) return xd == yd &amp;&amp; xf != nil &amp;&amp; yf != nil &amp;&amp; xf != yf }

