// date 2023/12/04 func searchInsert(nums []int, target int) int { n := len(nums) left, right := 0, n-1 // first equal or larger for left &lt;= right { mid := (left + right) / 2 if nums[mid] &lt; target { left = mid + 1 } else { right = mid - 1 } } return left }

74 搜索二维矩阵-中等# 题目：
给你一个满足下述两条属性的 m x n 整数矩阵：
每行中的整数从左到右按非严格递增顺序排列。 每行的第一个整数大于前一行的最后一个整数。 给你一个整数 target ，如果 target 在矩阵中，返回 true ；否则，返回 false 。
分析：
